pub struct Executor<'a, T: Transaction> {
    /// The transaction used to execute the plan.
    txn: &'a T,
}

impl<'a, T: Transaction> Executor<'a, T> {
    /// Creates a new executor.
    pub fn new(txn: &'a T) -> Self {
        Self { txn }
    }

    /// Executes a plan, returning an execution result.
    pub fn execute(&mut self, plan: Plan) -> Result<ExecutionResult> {
        match plan {
            Plan::CreateTable { schema } => {
                self.txn.create_table(schema)?;
                Ok(ExecutionResult::CreateTable {
                    name: schema.name,
                })
            }
            Plan::DropTable { name, if_exists } => {
                let existed = self.txn.drop_table(&name, if_exists)?;
                Ok(ExecutionResult::DropTable { name, existed })
            }
            Plan::Delete { table, primary_key, source } => {
                let count = self.delete(&table, primary_key, self.execute_node(source)?)?;
                Ok(ExecutionResult::Delete { count })
            }
            Plan::Insert { table, column_map, source } => {
                let count = self.insert(table, column_map, self.execute_node(source)?)?;
                Ok(ExecutionResult::Insert { count })
            }
            Plan::Update { table, primary_key, source, expressions } => {
                let count = self.update(&table, primary_key, self.execute_node(source)?, expressions)?;
                Ok(ExecutionResult::Update { count })
            }
            Plan::Select(source) => {
                let rows = self.execute_node(source)?;
                let columns = rows.columns();
                Ok(ExecutionResult::Select { columns, rows })
            }
        }
    }

    /// Recursively executes a query plan node, returning a row iterator.
    fn execute_node(&mut self, node: Node) -> Result<Rows> {
        match node {
            Node::Scan { table, filter, alias: _ } => {
                Ok(self.txn.scan(&table.name, filter)?)
            }
            Node::Filter { source, predicate } => {
                let source = self.execute_node(*source)?;
                Ok(Box::new(source.filter(move |row| {
                    match &row {
                        Ok(row) => {
                            match predicate.evaluate(Some(row)) {
                                Ok(Value::Boolean(b)) => b,
                                _ => true,
                            }
                        }
                        Err(_) => false,
                    }
                })))
            }
            Node::Aggregate { source, group_by, aggregates } => {
                let source = self.execute_node(*source)?;
                let mut aggregator = Aggregator::new(group_by, aggregates);
                aggregator.add_rows(source)?;
                Ok(aggregator.into_rows())
            }
            Node::Projection { source, expressions, aliases } => {
                let source = self.execute_node(*source)?;
                Ok(Box::new(source.map(move |row| {
                    let row = row?;
                    let mut new_row = Vec::new();
                    for expr in &expressions {
                        new_row.push(expr.evaluate(Some(&row))?);
                    }
                    Ok(new_row)
                })))
            }
            Node::Remap { source, targets } => {
                let source = self.execute_node(*source)?;
                Ok(Box::new(source.map(move |row| {
                    let row = row?;
                    let mut new_row = Vec::new();
                    for target in &targets {
                        match target {
                            Some(&idx) => new_row.push(row[idx].clone()),
                            None => new_row.push(Value::Null),
                        }
                    }
                    Ok(new_row)
                })))
            }
            Node::Order { source, key } => {
                let source = self.execute_node(*source)?;
                Self::order(source, key)
            }
            Node::Limit { source, limit } => {
                let source = self.execute_node(*source)?;
                Ok(Box::new(source.take(limit)))
            }
            Node::Offset { source, offset } => {
                let source = self.execute_node(*source)?;
                Ok(Box::new(source.skip(offset)))
            }
            Node::Values { rows } => {
                let rows: Result<Vec<Row>> = rows
                    .into_iter()
                    .map(|row| {
                        row.into_iter()
                            .map(|expr| expr.evaluate(None))
                            .collect()
                    })
                    .collect();
                Ok(Box::new(rows.into_iter().map(|r| r.map_err(|e| e.into()))))
            }
            Node::Nothing { columns: _ } => {
                Ok(Box::new(std::iter::empty()))
            }
            Node::KeyLookup { table, keys, alias: _ } => {
                let rows = self.txn.get(&table.name, &keys)?;
                Ok(Box::new(rows.into_iter().map(|r| Ok(r))))
            }
            Node::IndexLookup { table, column, values, alias: _ } => {
                let ids = self.txn.lookup_index(&table.name, &table.columns[column].name, &values)?;
                let ids: Vec<Value> = ids.into_iter().collect();
                let rows = self.txn.get(&table.name, &ids)?;
                Ok(Box::new(rows.into_iter().map(|r| Ok(r))))
            }
            Node::HashJoin { left, left_column, right, right_column, outer } => {
                let left = self.execute_node(*left)?;
                let right = self.execute_node(*right)?;
                let joiner = HashJoiner::new(
                    left,
                    left_column,
                    right,
                    right_column,
                    right_column,
                    outer,
                )?;
                Ok(Box::new(joiner))
            }
            Node::NestedLoopJoin { left, right, predicate, outer } => {
                let left = self.execute_node(*left)?;
                let right = self.execute_node(*right)?;
                let joiner = NestedLoopJoiner::new(
                    left,
                    right,
                    right.columns(),
                    predicate,
                    outer,
                );
                Ok(Box::new(joiner))
            }
        }
    }

    /// DELETE: deletes rows.
    fn delete(&self, table: &str, primary_key: usize, source: Rows) -> Result<u64> {
        let mut count = 0;
        for row in source {
            let row = row?;
            let id = row[primary_key].clone();
            self.txn.delete(table, &[id])?;
            count += 1;
        }
        Ok(count)
    }

    /// INSERT: inserts rows into a table from the given source.
    fn insert(
        &self,
        table: Table,
        column_map: Option<HashMap<usize, usize>>,
        mut source: Rows,
    ) -> Result<u64> {
        let mut rows = Vec::new();
        for row in source {
            let row = row?;
            let mut new_row = vec![Value::Null; table.columns.len()];
            if let Some(map) = &column_map {
                for (i, &col_idx) in map.iter() {
                    if *i < row.len() {
                        new_row[col_idx] = row[*i].clone();
                    }
                }
            } else {
                for (i, val) in row.into_iter().enumerate() {
                    if i < new_row.len() {
                        new_row[i] = val;
                    }
                }
            }
            rows.push(new_row);
        }
        self.txn.insert(&table.name, rows)?;
        Ok(rows.len() as u64)
    }

    /// UPDATE: updates rows passed in from the source.
    fn update(
        &self,
        table: &str,
        primary_key: usize,
        mut source: Rows,
        expressions: Vec<(usize, Option<Expression>)>,
    ) -> Result<u64> {
        let mut count = 0;
        let mut updates = BTreeMap::new();

        for row in source {
            let row = row?;
            let id = row[primary_key].clone();

            let mut new_row = row.clone();
            for (col_idx, expr) in &expressions {
                if let Some(expr) = expr {
                    new_row[*col_idx] = expr.evaluate(Some(&row))?;
                }
            }

            updates.insert(id, new_row);
            count += 1;
        }

        self.txn.update(table, updates)?;
        Ok(count)
    }

    /// Sorts the input rows.
    fn order(source: Rows, order: Vec<(Expression, Direction)>) -> Result<Rows> {
        let mut rows: Vec<Row> = source.collect::<Result<_>>()?;
        rows.sort_by(|a, b| {
            for (expr, dir) in &order {
                let a_val = expr.evaluate(Some(a))?;
                let b_val = expr.evaluate(Some(b))?;
                let cmp = a_val.cmp(&b_val);
                match dir {
                    Direction::Ascending => {
                        if cmp != Ordering::Equal {
                            return cmp;
                        }
                    }
                    Direction::Descending => {
                        if cmp != Ordering::Equal {
                            return cmp.reverse();
                        }
                    }
                }
            }
            Ordering::Equal
        });
        Ok(Box::new(rows.into_iter().map(Ok)))
    }
}
